const container=document.getElementById("profileContainer"),params=new URLSearchParams(window.location.search),profileId=params.get("id"),SERVER_BASE="https://api.buildskil.com";async function loadProfile(){if(!profileId){container.innerHTML="<p>Profile not found</p>";return}try{showLoader("loading...");const e=await fetch(`${SERVER_BASE}/api/profiles/${profileId}`);if(!e.ok){container.innerHTML="<p>Profile not available</p>";return}const d=await e.json();renderProfile(d)}catch(e){console.error(e),container.innerHTML="<p>Server error</p>"}finally{hideLoader()}}function renderProfile(e){const d=(e.media?.startsWith("http"),e.media);container.innerHTML=`

  <section class="profile-hero">

    <div class="hero-media">
      ${e.mediaType==="video"?`<video src="${d}" controls></video>`:`<img src="${e.media}?v=${Date.now()}" alt="${e.name}" />`}
    </div>

    <div class="hero-info">
      <h1>
        ${e.name}
        ${e.verified?'<span class="verify-badge">\u2714 Verified</span>':""}
      </h1>

      <span class="badge">${e.role||""}, ${e.category||""}</span>

      <div class="meta">
        <span>\u2B50 ${e.experience||"\u2014"} yrs</span>
        <span>\u{1F4CD} ${e.location||""}, ${e.state||""}, ${e.district||""}</span>
      </div>

      <div class="profile-actions">
        <a href="tel:${e.phone}" class="btn call">\u{1F4DE} Call</a>
        <a href="https://wa.me/${e.phone.replace(/\D/g,"")}" target="_blank" class="btn whatsapp">\u{1F7E2} WhatsApp</a>
      </div>

    </div>
  </section>


  <section class="profile-details">

    <h3>About Work</h3>
    <p>${e.description||"No details available"}</p>

    ${e.skills?.length?`
        <h3>Skills</h3>
        <div class="skills">
          ${e.skills.map(i=>`<span>${i}</span>`).join("")}
        </div>`:""}
    ${e.languages?.length?`<h3>Languages</h3><p>${e.languages.join(", ")}</p>`:""}
    </section>
    ${e.album?.length?`
         <section class="profile-gallery">
        <h3>Work Gallery</h3>
        <div class="gallery">
          ${e.album.map(i=>`<img src="${i.url}" />`).join("")}
        </div>
         </section>`:""}
  `;const p=document.querySelectorAll(".gallery img"),r=Array.from(p).map(i=>i.src);p.forEach((i,v)=>{i.addEventListener("click",()=>{let a=v;const n=document.createElement("div");n.className="lightbox";const h=document.createElement("img");h.src=r[a],n.appendChild(h);const l=document.createElement("div");l.className="nav prev",l.textContent="\u2039";const c=document.createElement("div");c.className="nav next",c.textContent="\u203A",n.appendChild(l),n.appendChild(c),document.body.appendChild(n),n.addEventListener("click",t=>{t.target===n&&n.remove()});function s(t){a=(t+r.length)%r.length,h.src=r[a]}l.addEventListener("click",t=>{t.stopPropagation(),s(a-1)}),c.addEventListener("click",t=>{t.stopPropagation(),s(a+1)});let m=0;n.addEventListener("touchstart",t=>{m=t.touches[0].clientX},{passive:!0}),n.addEventListener("touchend",t=>{const o=t.changedTouches[0].clientX;o-m>50&&s(a-1),m-o>50&&s(a+1)},{passive:!0}),document.addEventListener("keydown",function(o){o.key==="Escape"&&n.remove(),o.key==="ArrowLeft"&&s(a-1),o.key==="ArrowRight"&&s(a+1)},{once:!0})})})}const backBtn=document.querySelector(".back-btn");backBtn.addEventListener("click",()=>{window.history.length>1?history.back():window.location.href="landing.html"});const pageLoader=document.getElementById("pageLoader");function showLoader(e="Please wait..."){pageLoader.querySelector("p").textContent=e,pageLoader.classList.add("active")}function hideLoader(){pageLoader.classList.remove("active")}loadProfile();
